// Keep Bootstrap utilities used by older forms inside the current admin shell.
const fs = require('node:fs');
const postcss = require('postcss');
const root = postcss.parse(fs.readFileSync('public/admin/css/bootstrap.css', 'utf8'));
root.walkRules(rule => {
  if (rule.parent.type === 'atrule' && /keyframes$/i.test(rule.parent.name)) return;
  rule.selectors = rule.selectors.map(selector => ':where(.legacy-admin-content) ' + selector.replace(/^(?:html|body|:root)(?=\b|[.#:\s]|$)/, '').trim());
});
root.walkAtRules('charset', rule => rule.remove());
root.walkComments(comment => { if (!comment.text.includes('Bootstrap')) comment.remove(); });
fs.writeFileSync('public/common/admin-compat.css', '/* Generated by scripts/build-admin-compat.cjs from the existing Bootstrap stylesheet. */\n' + root.toString());

const vendorBundle = fs.readFileSync('public/admin/vendors/js/vendor.bundle.base.js', 'utf8');
const popperStart = vendorBundle.indexOf('/*\n Copyright (C) Federico');
const scrollbarStart = vendorBundle.indexOf('/*!\n * perfect-scrollbar');
if (popperStart < 0 || scrollbarStart < popperStart) throw new Error('Bootstrap bundle boundaries changed; review compatibility build.');
fs.writeFileSync('public/common/bootstrap-legacy.js', vendorBundle.slice(popperStart, scrollbarStart).replace(/^\/\/# sourceMappingURL=.*$/gm, ''));
